<?php
declare(strict_types=1);
session_start();
require dirname(__DIR__).'/config/config.php';
require_sign_in();
if(($_SESSION['role']??'')!=='system_admin'){http_response_code(403);exit('Only system admins can analyze subscription income.');}
$pdo=db();$uid=(int)$_SESSION['user_id'];$error='';$year=filter_var($_GET['year']??date('Y'),FILTER_VALIDATE_INT);if($year===false||$year<2000||$year>2100)$year=(int)date('Y');
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$id=(int)($_POST['subscription_id']??0);
    try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT x.id,x.school_id,x.academic_year,x.pupil_count,x.unit_price,x.discount_percent,x.total_amount,p.currency,p.name plan_name,s.name school_name FROM subscriptions x JOIN subscription_prices p ON p.id=x.price_id JOIN schools s ON s.id=x.school_id WHERE x.id=? AND x.status='pending' FOR UPDATE");$q->execute([$id]);$subscription=$q->fetch(PDO::FETCH_ASSOC);if(!$subscription)throw new DomainException('This subscription is no longer awaiting payment confirmation.');$q=$pdo->prepare("UPDATE subscriptions SET status='active' WHERE id=? AND status='pending'");$q->execute([$id]);if($q->rowCount()!==1)throw new DomainException('The subscription status changed. Refresh and try again.');$q=$pdo->prepare('INSERT INTO audit_logs (actor_id,action,entity_type,entity_id,details) VALUES (?,?,?,?,?)');$q->execute([$uid,'payment_confirmed','subscription',$id,json_encode(['school_id'=>(int)$subscription['school_id'],'school'=>$subscription['school_name'],'academic_year'=>(int)$subscription['academic_year'],'plan'=>$subscription['plan_name'],'currency'=>$subscription['currency'],'pupil_count'=>(int)$subscription['pupil_count'],'unit_price'=>(float)$subscription['unit_price'],'discount_percent'=>(float)$subscription['discount_percent'],'income'=>(float)$subscription['total_amount']])]);$pdo->commit();header('Location: subscription_analysis.php?year='.$year.'&confirmed=1');exit;}catch(DomainException $ex){if($pdo->inTransaction())$pdo->rollBack();$error=$ex->getMessage();}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$error='Payment confirmation could not be recorded. Check the database schema and try again.';}
}
$q=$pdo->prepare("SELECT currency,COUNT(*) subscription_count,SUM(total_amount) income,SUM(pupil_count) pupils FROM subscriptions x JOIN subscription_prices p ON p.id=x.price_id WHERE x.status='active' AND x.academic_year=? GROUP BY currency ORDER BY currency");$q->execute([$year]);$incomeRows=$q->fetchAll(PDO::FETCH_ASSOC);
$q=$pdo->prepare("SELECT currency,COUNT(*) request_count,SUM(total_amount) pending_value FROM subscriptions x JOIN subscription_prices p ON p.id=x.price_id WHERE x.status='pending' AND x.academic_year=? GROUP BY currency ORDER BY currency");$q->execute([$year]);$pendingRows=$q->fetchAll(PDO::FETCH_ASSOC);
$q=$pdo->prepare("SELECT x.id,s.name school_name,p.name plan_name,p.currency,p.billing_period,x.academic_year,x.pupil_count,x.unit_price,x.discount_percent,x.total_amount,x.starts_on,x.ends_on,DATEDIFF(x.ends_on,x.starts_on)+1 duration_days,DATEDIFF(x.ends_on,CURRENT_DATE) days_left FROM subscriptions x JOIN schools s ON s.id=x.school_id JOIN subscription_prices p ON p.id=x.price_id WHERE x.status='active' AND x.academic_year=? AND x.ends_on>=CURRENT_DATE ORDER BY x.ends_on,x.id");$q->execute([$year]);$activeRows=$q->fetchAll(PDO::FETCH_ASSOC);
$q=$pdo->prepare("SELECT x.id,s.name school_name,p.name plan_name,p.currency,p.billing_period,x.academic_year,x.pupil_count,x.unit_price,x.discount_percent,x.total_amount,x.starts_on,x.ends_on,DATEDIFF(x.ends_on,x.starts_on)+1 duration_days FROM subscriptions x JOIN schools s ON s.id=x.school_id JOIN subscription_prices p ON p.id=x.price_id WHERE x.status='pending' AND x.academic_year=? ORDER BY x.created_at");$q->execute([$year]);$pendingSubscriptions=$q->fetchAll(PDO::FETCH_ASSOC);
$q=$pdo->prepare("SELECT COUNT(*) FROM subscriptions WHERE academic_year=? AND (status='expired' OR (status='active' AND ends_on<CURRENT_DATE))");$q->execute([$year]);$expiredCount=(int)$q->fetchColumn();
function money_amount(array $row,string $key):string{return e($row['currency']).' '.e(number_format((float)$row[$key],2));}
$confirmed=isset($_GET['confirmed']);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Subscription income · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script></head><body><div class="app-shell"><aside class="sidebar" id="sidebar"><a class="brand" href="index.php"><span class="brand-mark">S</span><span>shule<span class="brand-lite">lite</span></span></a><div class="workspace-label">WORKSPACE</div><nav class="side-nav" aria-label="Main navigation"><a class="nav-item" href="index.php">⌂ &nbsp;Overview</a><a class="nav-item" href="schools.php">▦ &nbsp;Schools</a><a class="nav-item" href="subscriptions.php">◷ &nbsp;Subscriptions</a><a class="nav-item active" href="subscription_analysis.php" aria-current="page">▤ &nbsp;Income analysis</a><a class="nav-item" href="audit.php">◷ &nbsp;Audit log</a></nav><div class="sidebar-bottom"><a class="nav-item" href="logout.php">↪ &nbsp;Sign out</a></div></aside><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Workspace <span>/</span> Subscription income</div><div class="top-actions"><span class="role-chip">System Admin</span><div class="user-name"><?=e((string)($_SESSION['name']??''))?></div></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">FINANCE</div><h1>Subscription income</h1><p class="muted">Review confirmed subscription value, pending payment requests, and upcoming end dates.</p></div><a class="button" href="subscriptions.php">Manage prices and discounts</a></section><?php if($confirmed):?><div class="notice success" role="status">Payment confirmed and included in active subscription income. The action was added to the audit log.</div><?php endif;?><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><section class="content-section"><form class="results-entry-meta" method="get"><label for="analysis-year">Academic year<input id="analysis-year" type="number" name="year" min="2000" max="2100" value="<?=$year?>"></label><button class="button" type="submit">Analyze year</button></form><p class="muted">Income is included after a system admin confirms payment. Totals are grouped by currency and use the subscription’s saved pupil count, rate, and discount.</p></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">CONFIRMED SUBSCRIPTIONS</div><h2>Recorded income · <?=$year?></h2></div></div><?php if(!$incomeRows):?><div class="empty-state"><h3>No confirmed income for <?=$year?></h3><p>Confirm a pending payment below to include that subscription in the analysis.</p></div><?php else:?><div class="metric-grid"><?php foreach($incomeRows as $income):?><article class="metric-card"><div class="metric-label"><?=e($income['currency'])?> · CONFIRMED INCOME</div><div class="metric-value"><?=e(number_format((float)$income['income'],2))?></div><div class="metric-note"><?=number_format((int)$income['subscription_count'])?> subscriptions · <?=number_format((int)$income['pupils'])?> pupil enrolments</div></article><?php endforeach;?></div><?php endif;?></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">RENEWALS</div><h2>Active subscriptions and end dates</h2><p class="muted"><?=$expiredCount?> expired subscription<?=($expiredCount===1?'':'s')?> recorded for <?=$year?>.</p></div><span class="count-pill"><?=count($activeRows)?> active</span></div><?php if(!$activeRows):?><p class="muted">No active subscriptions for this year.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>School</th><th>Plan</th><th>Pupils</th><th>Rate per pupil</th><th>Discount</th><th>Income</th><th>Duration</th><th>Subscription dates</th><th>Days left</th></tr></thead><tbody><?php foreach($activeRows as $s):?><tr><td><?=e($s['school_name'])?></td><td><?=e($s['plan_name'])?></td><td><?=number_format((int)$s['pupil_count'])?></td><td><?=e($s['currency'])?> <?=e(number_format((float)$s['unit_price'],2))?></td><td><?=e(number_format((float)$s['discount_percent'],2))?>%</td><td><?=e($s['currency'])?> <?=e(number_format((float)$s['total_amount'],2))?></td><td><?=e(ucfirst($s['billing_period']))?> · <?=number_format((int)$s['duration_days'])?> days</td><td><?=e(date('j M Y',strtotime($s['starts_on'])))?> – <?=e(date('j M Y',strtotime($s['ends_on'])))?></td><td><?php if((int)$s['days_left']<=30):?><span class="count-pill"><?=$s['days_left']?> day<?=((int)$s['days_left']===1?'':'s')?></span><?php else:?><?=$s['days_left']?> days<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">AWAITING PAYMENT</div><h2>Pending subscription requests</h2></div><span class="count-pill"><?=count($pendingSubscriptions)?> pending</span></div><?php foreach($pendingRows as $pending):?><p><strong><?=money_amount($pending,'pending_value')?></strong> pending in <?=e($pending['request_count'])?> request<?=((int)$pending['request_count']===1?'':'s')?> (<?=$year?>)</p><?php endforeach;?><?php if(!$pendingSubscriptions):?><p class="muted">No pending requests for this year.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>School</th><th>Plan</th><th>Year</th><th>Pupils</th><th>Discount</th><th>Requested amount</th><th>Duration</th><th>Subscription dates</th><th>Action</th></tr></thead><tbody><?php foreach($pendingSubscriptions as $s):?><tr><td><?=e($s['school_name'])?></td><td><?=e($s['plan_name'])?></td><td><?=$s['academic_year']?></td><td><?=number_format((int)$s['pupil_count'])?></td><td><?=e(number_format((float)$s['discount_percent'],2))?>%</td><td><?=e($s['currency'])?> <?=e(number_format((float)$s['total_amount'],2))?></td><td><?=e(ucfirst($s['billing_period']))?> · <?=number_format((int)$s['duration_days'])?> days</td><td><?=e($s['starts_on'])?> – <?=e($s['ends_on'])?></td><td><form method="post" onsubmit="return confirm('Confirm the payment was received and activate this subscription?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="subscription_id" value="<?=$s['id']?>"><button class="button primary" type="submit">Confirm payment</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div></main></div></body></html>
